#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

// Minimum cost to make a non-decreasing; new values drawn from the distinct original values.
static ll nondecreasingCost(const vector<ll>& a, const vector<ll>& vals) {
    int k = vals.size();
    vector<ll> dp(k), nd(k);
    for (int j = 0; j < k; j++) dp[j] = llabs(a[0] - vals[j]);
    for (size_t i = 1; i < a.size(); i++) {
        ll best = LLONG_MAX;
        for (int j = 0; j < k; j++) {
            best = min(best, dp[j]);
            nd[j] = best + llabs(a[i] - vals[j]);
        }
        swap(dp, nd);
    }
    return *min_element(dp.begin(), dp.end());
}

int main() {
    int n;
    scanf("%d", &n);
    vector<ll> a(n);
    for (auto& x : a) scanf("%lld", &x);
    vector<ll> vals(a);
    sort(vals.begin(), vals.end());
    vals.erase(unique(vals.begin(), vals.end()), vals.end());
    ll up = nondecreasingCost(a, vals);
    reverse(a.begin(), a.end());
    printf("%lld\n", min(up, nondecreasingCost(a, vals)));
}

import java.io.*;
import java.util.*;

public class Main {
    // Minimum cost to make a non-decreasing; new values drawn from the distinct original values.
    static long nondecreasingCost(long[] a, long[] vals) {
        int k = vals.length;
        long[] dp = new long[k], nd = new long[k];
        for (int j = 0; j < k; j++) dp[j] = Math.abs(a[0] - vals[j]);
        for (int i = 1; i < a.length; i++) {
            long best = Long.MAX_VALUE;
            for (int j = 0; j < k; j++) {
                best = Math.min(best, dp[j]);
                nd[j] = best + Math.abs(a[i] - vals[j]);
            }
            long[] t = dp; dp = nd; nd = t;
        }
        long r = Long.MAX_VALUE;
        for (long v : dp) r = Math.min(r, v);
        return r;
    }

    public static void main(String[] args) throws IOException {
        StringTokenizer st = new StringTokenizer(new String(System.in.readAllBytes()));
        int n = Integer.parseInt(st.nextToken());
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = Long.parseLong(st.nextToken());
        long[] vals = Arrays.stream(a).sorted().distinct().toArray();
        long up = nondecreasingCost(a, vals);
        long[] rev = new long[n];
        for (int i = 0; i < n; i++) rev[i] = a[n - 1 - i];
        System.out.println(Math.min(up, nondecreasingCost(rev, vals)));
    }
}

package main

import (
	"bufio"
	"fmt"
	"math"
	"os"
	"slices"
	"strconv"
)

func abs(x int64) int64 {
	if x < 0 {
		return -x
	}
	return x
}

// Minimum cost to make a non-decreasing; new values drawn from the distinct original values.
func nondecreasingCost(a, vals []int64) int64 {
	k := len(vals)
	dp, nd := make([]int64, k), make([]int64, k)
	for j, v := range vals {
		dp[j] = abs(a[0] - v)
	}
	for _, x := range a[1:] {
		best := int64(math.MaxInt64)
		for j, v := range vals {
			best = min(best, dp[j])
			nd[j] = best + abs(x-v)
		}
		dp, nd = nd, dp
	}
	return slices.Min(dp)
}

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<26)
	sc.Split(bufio.ScanWords)
	next := func() int64 { sc.Scan(); v, _ := strconv.ParseInt(sc.Text(), 10, 64); return v }
	n := int(next())
	a := make([]int64, n)
	for i := range a {
		a[i] = next()
	}
	vals := slices.Clone(a)
	slices.Sort(vals)
	vals = slices.Compact(vals)
	up := nondecreasingCost(a, vals)
	slices.Reverse(a)
	fmt.Println(min(up, nondecreasingCost(a, vals)))
}
